import{_ as o,o as p,c as e,am as a}from"./chunks/framework._FJXuPhs.js";const g=JSON.parse('{"title":"apollo服务在Linux系统中的服务安装","description":"","frontmatter":{"title":"apollo服务在Linux系统中的服务安装","excerpt":"摘要","date":"2024-12-16 22:39:07","updated":"2024-12-16 22:39:07"},"headers":[],"relativePath":"框架/微服务分布式/Apollo配置使用/apollo服务在Linux系统中的服务安装.md","filePath":"框架/微服务分布式/Apollo配置使用/apollo服务在Linux系统中的服务安装.md","lastUpdated":null}'),t={name:"框架/微服务分布式/Apollo配置使用/apollo服务在Linux系统中的服务安装.md"};function r(i,l,c,s,n,u){return p(),e("div",null,[...l[0]||(l[0]=[a('<h3 id="安装包下载" tabindex="-1">安装包下载 <a class="header-anchor" href="#安装包下载" aria-label="Permalink to &quot;安装包下载&quot;">​</a></h3><ul><li>源码 <ul><li><code>git clone https://github.com/ctripcorp/apollo</code></li></ul></li><li>安装包 <ul><li>下载安装包 地址： <a href="https://github.com/ctripcorp/apollo/releases" target="_blank" rel="noreferrer">https://github.com/ctripcorp/apollo/releases</a></li></ul></li></ul><h3 id="docker-的方式启动-apollo" tabindex="-1">docker 的方式启动 apollo <a class="header-anchor" href="#docker-的方式启动-apollo" aria-label="Permalink to &quot;docker 的方式启动 apollo&quot;">​</a></h3><p>运行之前先创建运行一下数据库文件： <a href="https://github.com/apolloconfig/apollo/tree/master/scripts/sql/src" target="_blank" rel="noreferrer">https://github.com/apolloconfig/apollo/tree/master/scripts/sql/src</a></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20241216224953.png" alt="image.png"></p><p>1、使用docker搜索镜像</p><p>执行docker命令进行镜像搜索</p><p>docker search apolloconfig/apollo</p><p>执行成功后，可以查看到apollo的三个服务容器镜像。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20241217100910.png" alt="image.png"></p><p>2、拉取apollo镜像</p><p>执行docker pull命令进行镜像拉取，版本自行选择，默认拉取最新的镜像资源。</p><p>docker pull apolloconfig/apollo-configservice:latest</p><p>docker pull apolloconfig/apollo-adminservice:latest</p><p>docker pull apolloconfig/apollo-portal:latest</p><p>3、启动Apollo</p><p>拉取完docker镜像后，就可以直接通过镜像创建apollo相关容器了，不需要额外的配置apollo的信息。可以在创建容器的时候配置相关参数。</p><p>安装没有实际进行，大概看了一下重要内容</p><ul><li>1、获取git项目中的SQL运行文件，建立两个DB数据库 <ul><li><strong>ApolloPortalDB</strong><ul><li>导入成功后，验证SQL：<code>select * from `ApolloPortalDB`.`ServerConfig`;</code></li></ul></li><li><strong>ApolloConfigDB</strong><ul><li>导入成功后，验证SQL：<code>select * from `ApolloConfigDB`.`ServerConfig`;</code></li></ul></li></ul></li></ul><p>总体看起来较为简单</p><p>待完成内容</p><ul><li>实际部署成功，并成功配置连接信息（数据库和注册中心地址），页面运行正常</li><li>看一下是否是有单机和集群的区别，看一下apollo 的实现原理</li><li>springboot 项目和 apollo 的集成操作，以及一些常见的操作记录</li></ul>',22)])])}const _=o(t,[["render",r]]);export{g as __pageData,_ as default};
